{"implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload['required_symbols'])

    # Build lookup and children map
    node_map = {}
    children_map = {}
    for node in nodes:
        node_id = node['id']
        node_map[node_id] = node
        children_map[node_id] = []
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children_map[parent].append(node['id'])

    retained = set(node_map.keys())
    removal_order = []

    # Precompute sorted list of node ids by depth descending, then id for tie-break
    sorted_ids = sorted(node_map.keys(), key=lambda nid: (-node_map[nid]['depth'], nid))

    changed = True
    while changed:
        changed = False
        for nid in sorted_ids:
            if nid not in retained:
                continue
            node = node_map[nid]
            if not node['removable']:
                continue
            # Never remove root or nodes whose symbol is required
            if nid == 'root' or node['symbol'] in required_symbols:
                continue
            # Check for retained children
            has_retained_child = False
            for cid in children_map[nid]:
                if cid in retained:
                    has_retained_child = True
                    break
            if has_retained_child:
                continue
            # Check if removing this node would cause any required symbol to disappear
            # Only the symbol of this node matters because its subtree is already gone
            if node['symbol'] in required_symbols:
                # Need another retained node with same symbol
                other_exists = False
                for other_id in retained:
                    if other_id != nid and node_map[other_id]['symbol'] == node['symbol']:
                        other_exists = True
                        break
                if not other_exists:
                    continue
            # Perform removal
            retained.remove(nid)
            removal_order.append(nid)
            changed = True
            # Break out of for loop to restart scan (avoids index issues)
            break

    return {
        'retained_ids': sorted(retained),
        'removal_order': removal_order
    }"}
